 using namespace std::chrono_literals;
 using namespace Qt::StringLiterals;

@@ -1308,6 +1311,10 @@ bool PanelView::event(QEvent *e)

     bool rc = ContainmentView::event(e);

+    if (e->type() == QEvent::Expose || e->type() == QEvent::Show || e->type() == QEvent::Hide) {
+        updatePolishWhileHidden();
+    }
+
     // PanelView does not take focus, but we want any users tracking focus
     // to act like they've lost focus when the panel is clicked and it was not used by another other mouse item
     if (e->type() == QEvent::MouseButtonPress) {
@@ -1325,6 +1332,24 @@ bool PanelView::event(QEvent *e)
     return rc;
 }

+void PanelView::updatePolishWhileHidden()
+{
+    // Items are only polished when the window is rendered, so a hidden auto-hide panel would lay out
+    // what changed meanwhile (e.g. closed tasks) only once shown again, and animate it in front of the user.
+    if (isVisible() && !isExposed()) {
+        if (!m_polishWhileHiddenConnection) {
+            m_polishWhileHiddenConnection = connect(QAbstractEventDispatcher::instance(), &QAbstractEventDispatcher::aboutToBlock, this, [this] {
+                auto windowPrivate = QQuickWindowPrivate::get(this);
+                if (!windowPrivate->itemsToPolish.isEmpty()) {
+                    windowPrivate->polishItems();
+                }
+            });
+        }
+    } else {
+        disconnect(m_polishWhileHiddenConnection);
+    }
+}
